def load_transcript(transcript_path: Path) -> list[dict] | None:
    """Load Claude Code / Codex transcript JSONL.

    Returns:
      - list[dict]: parsed events (may be empty if file only has blank/invalid lines)
      - None: file is missing OR an I/O/decode failure occurred
    """
    if not transcript_path.exists():
        return None
    try:
        events = []
        # Prefer binary read + decode so a concurrent partial write that lands a
        # non-UTF8 tail does not blow up the whole load.
        raw = transcript_path.read_bytes()
        text = raw.decode("utf-8", errors="replace")
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                events.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        return events
    except Exception:
        return None
